using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using BotZone.Contracts;
namespace BotZone.Infrastructure.Services;

public sealed partial class CommandService(SqlStore sql,CommerceService commerce,InventoryService inventory,LandingService landing,AfterSalesService afterSales)
{
 public Task<object> Execute(Actor actor,CommandRequest request)=>sql.Transaction<object>(actor,async()=>{
  Access.Ensure(Guid.TryParse(request.Key,out _),"VALIDATION_ERROR","Lệnh cần idempotency key UUID.",400);Access.Ensure(request.Command is {Length: >=1 and <=80}&&request.Input.ValueKind==JsonValueKind.Object,"VALIDATION_ERROR","Lệnh không hợp lệ.",400);
  Permission(actor,request.Command,request.Input);if(actor.Role=="customer"&&request.Command=="record_payment"){var permitted=await sql.One("SELECT a.method FROM payment_attempts a JOIN orders o ON o.id=a.order_id WHERE a.id=$1 AND o.customer_id=$2",request.Input.Id("attemptId"),actor.Id);Access.Ensure(permitted.S("method") is "momo" or "visa","FORBIDDEN","Khách chỉ được chọn kịch bản MoMo hoặc Visa mô phỏng cho đơn của mình.",403);}if(actor.Role=="customer"&&request.Command is "start_payment" or "cancel_order")await sql.One("SELECT id FROM orders WHERE id=$1 AND customer_id=$2",request.Input.Id("orderId"),actor.Id);var scope=actor.Id+":"+request.Command;var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(request.Input.GetRawText())));var old=await sql.Optional("SELECT request_hash,result FROM idempotency_records WHERE scope=$1 AND key=$2",scope,request.Key);if(old is not null){Access.Ensure(old.S("request_hash")==hash,"IDEMPOTENCY_CONFLICT","Key này đã được dùng với nội dung khác.");return old.J("result");}
  var before=await BeforeCommand(request.Command,request.Input);var result=await commerce.Handle(actor,request.Command,request.Input,request.Key)??await inventory.Handle(actor,request.Command,request.Input,request.Key)??await landing.Handle(actor,request.Command,request.Input,request.Key)??await afterSales.Handle(actor,request.Command,request.Input,request.Key)??await Catalogue(actor,request.Command,request.Input)??await Profile(actor,request.Command,request.Input)??throw new BusinessException("UNKNOWN_COMMAND","Lệnh chưa được hỗ trợ.",400);
  var json=Values.Json(result);await sql.Exec("INSERT INTO idempotency_records(scope,key,request_hash,result) VALUES($1,$2,$3,$4::jsonb)",scope,request.Key,hash,json);var audited=request.Command=="preview_landing"?Values.Json(new{previewGranted=true}):json;await sql.Exec("INSERT INTO audit_events(actor_user_id,action,entity_type,before_data,after_data,reason,correlation_id) VALUES($1,$2,'command',$6::jsonb,$3::jsonb,$4,$5)",actor.Id,request.Command,audited,request.Input.Text("reason",""),request.Key,before is null?null:Values.Json(before));return result;
 });
 async Task<object?> Profile(Actor a,string command,JsonElement p){switch(command){
 case "save_profile":{Access.Require(a,"customer");var name=p.Text("name").Trim();var phone=p.Text("phone","").Trim();Access.Ensure(name.Length is >=2 and <=100&&phone.Length<=20,"VALIDATION_ERROR","Tên hoặc số điện thoại không hợp lệ.",400);await sql.Exec("UPDATE \"user\" SET name=$2,phone_number=$3,updated_at=now() WHERE id=$1;INSERT INTO customer_profiles(user_id,display_name,phone) VALUES($1,$2,$3) ON CONFLICT(user_id) DO UPDATE SET display_name=excluded.display_name,phone=excluded.phone",a.Id,name,phone);return new{saved=true};}
 case "save_address":{Access.Require(a,"customer");foreach(var key in new[]{"recipient","phone","province","ward","addressLine"})Access.Ensure(p.Text(key).Trim().Length is >=2 and <=300,"VALIDATION_ERROR","Địa chỉ chưa đầy đủ.",400);var id=p.MaybeId("id");if(id.HasValue)await sql.One("SELECT id FROM addresses WHERE id=$1 AND user_id=$2 FOR UPDATE",id,a.Id);if(p.Bool("isDefault"))await sql.Exec("UPDATE addresses SET is_default=false WHERE user_id=$1",a.Id);return id.HasValue?await sql.One("UPDATE addresses SET recipient=$3,phone=$4,province=$5,ward=$6,address_line=$7,is_default=$8 WHERE id=$1 AND user_id=$2 RETURNING id",id,a.Id,p.Text("recipient"),p.Text("phone"),p.Text("province"),p.Text("ward"),p.Text("addressLine"),p.Bool("isDefault")):await sql.One("INSERT INTO addresses(user_id,recipient,phone,province,ward,address_line,is_default) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING id",a.Id,p.Text("recipient"),p.Text("phone"),p.Text("province"),p.Text("ward"),p.Text("addressLine"),p.Bool("isDefault"));}
 case "sync_wishlist":{Access.Require(a,"customer");var ids=p.Array("productIds").Select(v=>Guid.Parse(v.GetString()!)).Distinct().ToArray();Access.Ensure(ids.Length<=100,"VALIDATION_ERROR","Danh sách quá lớn.",400);await sql.Exec("DELETE FROM wishlists WHERE user_id=$1",a.Id);foreach(var id in ids)await sql.Exec("INSERT INTO wishlists(user_id,product_id) VALUES($1,$2)",a.Id,id);return new{saved=true};}
 case "read_notification":{await sql.Exec("UPDATE notifications SET read_at=COALESCE(read_at,now()) WHERE id=$1 AND recipient_user_id=$2",p.Id("id"),a.Id);return new{read=true};}
 case "update_variant":{Access.Require(a,"owner");var months=p.Int("standardWarrantyMonths");Access.Ensure(months is >=0 and <=60,"VALIDATION_ERROR","Thời hạn bảo hành không hợp lệ.",400);long? fee=p.TryGetProperty("careFeeVnd",out var cv)&&cv.ValueKind==JsonValueKind.Null?null:p.Money("careFeeVnd");return await sql.One("UPDATE product_variants SET price_vnd=$2,active=$3,care_fee_vnd=$4,standard_warranty_months=$5 WHERE id=$1 RETURNING id,sku,price_vnd,active,care_fee_vnd,standard_warranty_months",p.Id("variantId"),p.Money("priceVnd"),p.Bool("active"),fee,months);}
 case "update_translation":{Access.Require(a,"content_staff");string locale=p.Text("locale"),status=p.Text("contentStatus");Access.Ensure(locale is "vi" or "en"&&status is "draft" or "published","VALIDATION_ERROR","Ngôn ngữ hoặc trạng thái không hợp lệ.",400);string name=p.Text("name").Trim(),description=p.Text("description").Trim(),seo=p.Text("seoTitle").Trim();Access.Ensure(name.Length is >=1 and <=200&&description.Length is >=1 and <=10000&&seo.Length is >=1 and <=200,"VALIDATION_ERROR","Nội dung vượt giới hạn.",400);return await sql.One("INSERT INTO product_translations(product_id,locale,name,description,seo_title,content_status) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(product_id,locale) DO UPDATE SET name=excluded.name,description=excluded.description,seo_title=excluded.seo_title,content_status=excluded.content_status RETURNING product_id,locale,content_status",p.Id("productId"),locale,name,description,seo,status);}
 case "update_staff":{Access.Require(a,"owner");string id=p.Text("userId"),role=p.Text("role");Access.Ensure(new[]{"owner","order_staff","warehouse_staff","content_staff"}.Contains(role),"VALIDATION_ERROR","Vai trò không hợp lệ.",400);Reason(p);var old=await sql.Optional("SELECT * FROM staff_profiles WHERE user_id=$1 FOR UPDATE",id);if(old?.S("role")=="owner"&&old.B("active")&&(!p.Bool("active")||role!="owner")){var owners=await sql.One("SELECT count(*)::int n FROM staff_profiles WHERE role='owner' AND active");Access.Ensure(owners.I("n")>1,"STATE_CONFLICT","Phải giữ ít nhất một owner hoạt động.");}await sql.Exec("INSERT INTO staff_profiles(user_id,staff_code,role,active) VALUES($1,$2,$3,$4) ON CONFLICT(user_id) DO UPDATE SET staff_code=excluded.staff_code,role=excluded.role,active=excluded.active",id,p.Text("staffCode"),role,p.Bool("active"));await sql.Exec("UPDATE auth_sessions SET revoked_at=now() WHERE user_id=$1 AND revoked_at IS NULL",id);return new{userId=id,role,active=p.Bool("active"),sessionsRevoked=true};}
 case "update_settings":
 case "save_settings":{Access.Require(a,"owner");Reason(p);var key=p.Text("key");Access.Ensure(new[]{"commerce","exchangeRateVnd","store","tradeIn"}.Contains(key),"VALIDATION_ERROR","Cấu hình này không được sửa qua ứng dụng.",400);var value=p.Field("value");ValidateSetting(key,value);if(key=="exchangeRateVnd")Access.Ensure(decimal.TryParse(value.ToString(),out var rate)&&rate>0&&rate<10000000,"VALIDATION_ERROR","Tỷ giá không hợp lệ.",400);var setting=await sql.One("INSERT INTO app_settings(key,value,version) VALUES($1,$2::jsonb,1) ON CONFLICT(key) DO UPDATE SET value=excluded.value,version=app_settings.version+1 RETURNING version",key,value.GetRawText());await sql.Exec("INSERT INTO setting_versions(key,version_no,value,changed_by) VALUES($1,$2,$3::jsonb,$4)",key,setting.I("version"),value.GetRawText(),a.Id);return new{key,version=setting.I("version")};}
 case "create_promotion":return await Promotion(a,p);
 case "save_supplier":{Access.Require(a,"owner","warehouse_staff");var id=p.MaybeId("id")??Guid.NewGuid();await sql.Exec("INSERT INTO suppliers(id,code,name,contact,active) VALUES($1,$2,$3,$4,$5) ON CONFLICT(id) DO UPDATE SET code=excluded.code,name=excluded.name,contact=excluded.contact,active=excluded.active",id,p.Text("code"),p.Text("name"),p.Text("contact"),p.Bool("active",true));return new{id};}
 default:return null;}}
 static void Reason(JsonElement p)=>Access.Ensure(p.Text("reason").Trim().Length is >=5 and <=2000,"VALIDATION_ERROR","Cần lý do từ 5 đến 2.000 ký tự.",400);
 async Task<object> Promotion(Actor a,JsonElement p){Access.Require(a,"owner");string code=p.Text("code").Trim().ToUpperInvariant(),type=p.Text("discountType");long value=p.Money("value");Access.Ensure(code.Length is >=2 and <=40&&type is "fixed" or "percentage"&&value>0&&(type!="percentage"||value<=100),"VALIDATION_ERROR","Mã hoặc mức giảm không hợp lệ.",400);Access.Ensure(DateTimeOffset.TryParse(p.Text("startsAt"),out var start)&&DateTimeOffset.TryParse(p.Text("endsAt"),out var end)&&end>start,"VALIDATION_ERROR","Thời gian không hợp lệ.",400);var ends=DateTimeOffset.Parse(p.Text("endsAt")).UtcDateTime;var targets=p.TryGetProperty("targets",out var tv)?tv.EnumerateArray().ToArray():[];bool all=p.Bool("allProducts",true);Access.Ensure(all?targets.Length==0:targets.Length>0,"VALIDATION_ERROR","Chọn phạm vi nhất quán.",400);int? max=p.Int("maxUses")>0?p.Int("maxUses"):null,per=p.Int("maxUsesPerCustomer")>0?p.Int("maxUsesPerCustomer"):null;long? cap=p.TryGetProperty("maxDiscountVnd",out var capv)&&capv.ValueKind!=JsonValueKind.Null?p.Money("maxDiscountVnd"):null;var promo=await sql.One("INSERT INTO promotions(code_normalized,active,max_uses,max_uses_per_customer) VALUES($1,$2,$3,$4) ON CONFLICT(code_normalized) DO UPDATE SET active=excluded.active,max_uses=excluded.max_uses,max_uses_per_customer=excluded.max_uses_per_customer RETURNING id",code,p.Bool("active",true),max,per);var version=await sql.One("INSERT INTO promotion_versions(promotion_id,version_no,discount_type,value,max_discount_vnd,min_purchase_vnd,starts_at,ends_at,all_products) SELECT $1,COALESCE(max(version_no),0)+1,$2,$3,$4,$5,$6,$7,$8 FROM promotion_versions WHERE promotion_id=$1 RETURNING id,version_no",promo.G("id"),type,value,cap,p.Money("minPurchaseVnd"),start.UtcDateTime,ends,all);foreach(var t in targets){Guid? v=t.MaybeId("variantId"),product=t.MaybeId("productId"),cat=t.MaybeId("categoryId");Access.Ensure(new[]{v,product,cat}.Count(x=>x.HasValue)==1,"VALIDATION_ERROR","Mỗi target chỉ chọn một loại.",400);await sql.Exec("INSERT INTO promotion_targets(promotion_version_id,variant_id,product_id,category_id) VALUES($1,$2,$3,$4)",version.G("id"),v,product,cat);}return new{promotionId=promo.G("id"),versionId=version.G("id"),version=version.I("version_no")};}
}
